pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // Rebinding keeps the public parameter (and signature) untouched while
    // allowing the `FnMut` closure to be called more than once.
    let mut job = job;
    for attempt in 0..config.max_attempts {
        match job() {
            Ok(()) => return Ok(()),
            // Only transient errors are retried, and only while a further
            // attempt is still available within `max_attempts`.
            Err(err) if err.is_transient() && attempt + 1 < config.max_attempts => {
                sleeper.sleep_ms(config.delay_ms(attempt));
            }
            Err(err) => return Err(err),
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn permanent_error_returns_immediately() {
        let config = RetryConfig::new(5, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("nope".to_string()))
        });
        assert_eq!(result, Err(RetryError::Permanent("nope".to_string())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn retries_transient_until_success() {
        let config = RetryConfig::new(5, 100, 1_000);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(RetryError::Transient("not yet".to_string()))
            } else {
                Ok(())
            }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![100, 200]);
    }

    #[test]
    fn max_attempts_bounds_transient_retries() {
        let config = RetryConfig::new(3, 10, 1_000);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("always".to_string()))
        });
        assert_eq!(result, Err(RetryError::Transient("always".to_string())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }
}

