+        let config = RetryConfig::new(5, 100, 1_000);
+        let mut sleeper = FakeSleeper::default();
+        let mut calls = 0;
+        let result = run_job(&config, &mut sleeper, || {
+            calls += 1;
+            if calls < 3 {
+                Err(RetryError::Transient("not yet".to_string()))
+            } else {
+                Ok(())
+            }
+        });
+        assert_eq!(result, Ok(()));
+        assert_eq!(calls, 3);
+        assert_eq!(sleeper.sleeps, vec![100, 200]);
+    }
+
+    #[test]
+    fn max_attempts_bounds_transient_retries() {
+        let config = RetryConfig::new(3, 10, 1_000);
+        let mut sleeper = FakeSleeper::default();
+        let mut calls = 0;
+        let result = run_job(&config, &mut sleeper, || {
+            calls += 1;
+            Err(RetryError::Transient("always".to_string()))
+        });
+        assert_eq!(result, Err(RetryError::Transient("always".to_string())));
+        assert_eq!(calls, 3);
+        assert_eq!(sleeper.sleeps, vec![10, 20]);
+    }
